/* Model creation/destruction functions */

void MODEL_mkTbRS::create_model(tSimStateHdl simHdl, bool master)
{
  sim_hdl = simHdl;
  init_reset_request_counters(sim_hdl);
  mkTbRS_instance = new MOD_mkTbRS(sim_hdl, "top", NULL);
  bk_get_or_define_clock(sim_hdl, "CLK");
  if (master)
  {
    bk_alter_clock(sim_hdl, bk_get_clock_by_name(sim_hdl, "CLK"), CLK_LOW, false, 0llu, 5llu, 5llu);
    bk_use_default_reset(sim_hdl);
  }
  bk_set_clock_event_fn(sim_hdl,
			bk_get_clock_by_name(sim_hdl, "CLK"),
			schedule_posedge_CLK,
			NULL,
			(tEdgeDirection)(POSEDGE));
  (mkTbRS_instance->INST_bb_mem_wrW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_mem_rdW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_cfgW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_planW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_putW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_rewW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_advW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_rdW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_bb_fixW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_rs_startW.set_clk_0)("CLK");
  (mkTbRS_instance->INST_rs_getW.set_clk_0)("CLK");
  (mkTbRS_instance->set_clk_0)("CLK");
}
void MODEL_mkTbRS::destroy_model()
{
  delete mkTbRS_instance;
  mkTbRS_instance = NULL;
}
void MODEL_mkTbRS::reset_model(bool asserted)
{
  (mkTbRS_instance->reset_RST_N)(asserted ? (tUInt8)0u : (tUInt8)1u);
}
void * MODEL_mkTbRS::get_instance()
{
  return mkTbRS_instance;
}

/* Fill in version numbers */
void MODEL_mkTbRS::get_version(char const **name, char const **build)
{
  *name = "2021.12.1";
  *build = "fd501401";
}

/* Get the model creation time */
time_t MODEL_mkTbRS::get_creation_time()
{
  
  /* Sat Nov  7 16:17:42 UTC 2026 */
  return 1794068262llu;
}

/* State dumping function */
void MODEL_mkTbRS::dump_state()
{
  (mkTbRS_instance->dump_state)(0u);
}

/* VCD dumping functions */
MOD_mkTbRS & mkTbRS_backing(tSimStateHdl simHdl)
{
  static MOD_mkTbRS *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTbRS(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
void MODEL_mkTbRS::dump_VCD_defs()
{
  (mkTbRS_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTbRS::dump_VCD(tVCDDumpType dt)
{
  (mkTbRS_instance->dump_VCD)(dt, vcd_depth(sim_hdl), mkTbRS_backing(sim_hdl));
}
